// Decimals of pi on the HDMI console and UART, streamed as they are computed:
// Rabinowitz-Wagon spigot (Dik Winter's compact form, 4 digits per pass, integer
// only), so the whole screen fills in a few seconds. A key at the end returns to
// the menu.
#include <stdint.h>
#include "fbcon.h"
#include "cpuhz.h"

#define IO_COUNTER (*(volatile uint32_t *)0x400020)
#define DIGITS     3141                 // int(pi * 1000)
#define GROUPS     ((DIGITS + 3) / 4)
#define LEN        (GROUPS * 14)

int printf(const char *fmt, ...);
int putchar(int c);

static uint32_t f[LEN + 1];
static const char ref[] = "";   // to colour each digit: green right, red wrong
static uint32_t bad;
#define IO_VIDEO (*(volatile uint32_t *)0x400800)

static void put(const char *s) { while (*s) con_putc(*s++); }

static void putn(uint32_t n)
{
    char b[12];
    int i = 11;
    b[i] = 0;
    do b[--i] = '0' + n % 10; while (n /= 10);
    put(b + i);
}

static uint32_t pos;

static void out(int c)
{
    putchar(c);
    // Digits use rows 3..23 and scroll there; row 24 stays empty, since fbcon
    // scrolls the whole screen (header too) once a character wraps past it.
    if (pos % 40 == 0 && pos / 40 >= 21) {
        volatile uint8_t *fb = (volatile uint8_t *)0x200000;
        for (int i = 3 * 8 * 320; i < 23 * 8 * 320; ++i) fb[i] = fb[i + 8 * 320];
        for (int i = 23 * 8 * 320; i < 24 * 8 * 320; ++i) fb[i] = 0;
    }
    con_at(pos % 40, pos / 40 >= 21 ? 23 : 3 + pos / 40);
    if (c != '.') {
        int ok = c == ref[pos - (pos > 0)];
        bad += !ok;
        con_setcolor(ok ? 2 : 3, 0);
    }
    con_putc(c);
    ++pos;
}

static void header(uint32_t digits, uint32_t t0)
{
    uint32_t ms = (IO_COUNTER - t0) / (CPU_HZ / 1000);
    con_at(0, 1);
    con_setcolor(15, 0);
    put("digits "); putn(digits); put("  wrong "); putn(bad); put("  ");
    putn(ms ? digits * 1000 / ms : 0); put("/s  ");
}

int main(void)
{
    con_init();
    IO_VIDEO = 2 << 16 | 0x0F0;
    IO_VIDEO = 3 << 16 | 0xF00;
    con_at(0, 0);
    put("Pi, Rabinowitz-Wagon spigot");
    for (int i = 0; i < LEN; ++i) f[i] = 2000;

    uint32_t t0 = IO_COUNTER, e = 0;
    for (int g = 0, c = LEN; c; c -= 14, ++g) {
        if (con_key() >= 0) return 0;              // any key: back to the menu
        uint32_t d = 0, k = c * 2, b = c;
        for (;;) {
            d += f[b] * 10000;
            f[b] = d % --k;
            d /= k--;
            if (!--b) break;
            d *= b;
        }
        uint32_t v = e + d / 10000;
        e = d % 10000;
        char s[5] = { '0' + v / 1000, '0' + v / 100 % 10, '0' + v / 10 % 10, '0' + v % 10, 0 };
        for (int i = 0; i < 4 && 4 * g + i < DIGITS; ++i) {
            out(s[i]);
            if (g == 0 && i == 0) out('.');
        }
        header(4 * g + 4 < DIGITS ? 4 * g + 4 : DIGITS, t0);
    }
    con_at(0, 2);
    put("done. Any key: menu");
    con_waitkey();
    return 0;
}
